import { test, expect } from '@playwright/test';

test.describe('Checkout Flow Sequential Async Steps', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should complete checkout flow with sequential async steps in correct order', async ({ page }) => {
    // Step 1: Verify initial state and click 'Continue'
    const continueButton = page.getByRole('button', { name: /continue/i });
    await expect(continueButton).toBeVisible();
    await continueButton.click();

    // Step 2: Verify shipping address form is visible
    const shippingForm = page.locator('[data-testid="shipping-form"]');
    await expect(shippingForm).toBeVisible();

    // Step 3: Fill in shipping address using getByLabel
    const addressInput = page.getByLabel(/street address/i);
    await addressInput.fill('123 Main St');

    const cityInput = page.getByLabel(/city/i);
    await cityInput.fill('Anytown');

    const zipInput = page.getByLabel(/zip code/i);
    await zipInput.fill('12345');

    // Step 4: Click 'Continue' to proceed to payment
    const nextButton = page.getByRole('button', { name: /continue/i });
    await expect(nextButton).toBeVisible();
    await nextButton.click();

    // Step 5: Verify payment form is visible
    const paymentForm = page.locator('[data-testid="payment-form"]');
    await expect(paymentForm).toBeVisible();

    // Step 6: Fill in payment details using getByLabel
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111234');

    const expiryInput = page.getByLabel(/expiry date/i);
    await expiryInput.fill('12/25');

    // Step 7: Click 'Continue' to proceed to review
    const reviewButton = page.getByRole('button', { name: /continue/i });
    await expect(reviewButton).toBeVisible();
    await reviewButton.click();

    // Step 8: Verify order review page is visible
    const reviewPage = page.locator('[data-testid="order-review"]');
    await expect(reviewPage).toBeVisible();

    // Step 9: Verify order summary contains correct data
    const orderTotal = page.getByText(/\$123.99/);
    await expect(orderTotal).toBeVisible();

    // Step 10: Click 'Place Order' button
    const placeOrderButton = page.getByRole('button', { name: /place order/i });
    await expect(placeOrderButton).toBeVisible();
    await placeOrderButton.click();

    // Step 11: Verify success message appears
    const successMessage = page.getByText(/order placed successfully/i);
    await expect(successMessage).toBeVisible();

    // Step 12: Verify confirmation page is displayed
    const confirmationPage = page.locator('[data-testid="confirmation-page"]');
    await expect(confirmationPage).toBeVisible();
  });

  test('should handle async step failure and prevent order submission', async ({ page }) => {
    // Step 1: Click 'Continue' to shipping
    const continueButton = page.getByRole('button', { name: /continue/i });
    await continueButton.click();

    // Step 2: Fill in shipping address
    const addressInput = page.getByLabel(/street address/i);
    await addressInput.fill('404 Not Found Lane');

    const cityInput = page.getByLabel(/city/i);
    await cityInput.fill('Errorville');

    const zipInput = page.getByLabel(/zip code/i);
    await zipInput.fill('99999');

    // Step 3: Click 'Continue' to payment
    const nextButton = page.getByRole('button', { name: /continue/i });
    await nextButton.click();

    // Step 4: Fill in payment details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111234');

    const expiryInput = page.getByLabel(/expiry date/i);
    await expiryInput.fill('12/25');

    // Step 5: Click 'Continue' to review
    const reviewButton = page.getByRole('button', { name: /continue/i });
    await reviewButton.click();

    // Step 6: Verify order review page is visible
    const reviewPage = page.locator('[data-testid="order-review"]');
    await expect(reviewPage).toBeVisible();

    // Step 7: Attempt to click 'Place Order' button
    const placeOrderButton = page.getByRole('button', { name: /place order/i });
    await expect(placeOrderButton).toBeVisible();

    // Step 8: Intercept the API call and simulate failure
    await page.route('**/api/checkout/submit', route => {
      route.abort('failed');
    });

    // Step 9: Click 'Place Order' button
    await placeOrderButton.click();

    // Step 10: Verify error message appears
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Step 11: Verify user remains on review page
    await expect(reviewPage).toBeVisible();

    // Step 12: Verify order confirmation page does not exist
    const confirmationPage = page.locator('[data-testid="confirmation-page"]');
    await expect(confirmationPage).not.toBeVisible();
  });
});
